const newsSample = "\ud83d\ude80 Taler ID 1.1.25\n\n\u0420\u0435\u043b\u0438\u0437 1.1.25 \u2014 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f.\n\n\ud83d\udccc \u0417\u0430\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439. \u0412\u0430\u0436\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u043c\u043e\u0436\u043d\u043e \u0437\u0430\u043a\u0440\u0435\u043f\u0438\u0442\u044c, \u0438 \u043e\u043d\u043e \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u043d\u0430 \u0432\u0438\u0434\u0443 \u0432 \u0448\u0430\u043f\u043a\u0435 \u0447\u0430\u0442\u0430 \u2014 \u0432 \u043b\u0438\u0447\u043d\u043e\u0439 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0435, \u0432 \u0433\u0440\u0443\u043f\u043f\u0435 \u0438 \u0432 \u043a\u0430\u043d\u0430\u043b\u0435. \u0417\u0430\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u043c\u043e\u0436\u043d\u043e \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e: \u043f\u043b\u0430\u0448\u043a\u0430 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u0445, \u0430 \u043f\u043e \u043d\u0430\u0436\u0430\u0442\u0438\u044e \u043b\u0438\u0441\u0442\u0430\u0435\u0442 \u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442 \u043a \u043d\u0443\u0436\u043d\u043e\u043c\u0443 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044e.\n\n\ud83d\udccb \u0421\u043f\u0438\u0441\u043e\u043a \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u0445. \u041e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u044d\u043a\u0440\u0430\u043d \u0441\u043e \u0432\u0441\u0435\u043c\u0438 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u043c\u0438 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f\u043c\u0438 \u0447\u0430\u0442\u0430: \u043e\u0442\u0442\u0443\u0434\u0430 \u043c\u043e\u0436\u043d\u043e \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043a \u043b\u044e\u0431\u043e\u043c\u0443, \u0441\u043d\u044f\u0442\u044c \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u0441 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u043b\u0438 \u0443\u0431\u0440\u0430\u0442\u044c \u0432\u0441\u0435 \u0441\u0440\u0430\u0437\u0443.\n\n\ud83d\ude48 \u041f\u043b\u0430\u0448\u043a\u0443 \u043c\u043e\u0436\u043d\u043e \u0441\u0432\u0435\u0440\u043d\u0443\u0442\u044c. \u0415\u0441\u043b\u0438 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u043e\u0435 \u0432\u0430\u043c \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435 \u043d\u0443\u0436\u043d\u043e, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u043a\u0440\u0435\u0441\u0442\u0438\u043a \u2014 \u043f\u043b\u0430\u0448\u043a\u0430 \u0441\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0443 \u0432\u0430\u0441 \u0438 \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f, \u043a\u043e\u0433\u0434\u0430 \u0437\u0430\u043a\u0440\u0435\u043f\u044f\u0442 \u0447\u0442\u043e-\u0442\u043e \u043d\u043e\u0432\u043e\u0435.\n\n\ud83c\udf99 \u0413\u043e\u043b\u043e\u0441\u043e\u043c. \u0410\u0441\u0441\u0438\u0441\u0442\u0435\u043d\u0442\u0430 \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0437\u0430\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u0438\u043b\u0438 \u043e\u0442\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0438 \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u0430\u0442\u044c, \u0447\u0442\u043e \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u043e \u0432 \u0447\u0430\u0442\u0435.\n\n\u0412 \u043b\u0438\u0447\u043d\u043e\u0439 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0435 \u0437\u0430\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u043c\u043e\u0436\u0435\u0442 \u043b\u044e\u0431\u043e\u0439 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a, \u0432 \u0433\u0440\u0443\u043f\u043f\u0430\u0445 \u0438 \u043a\u0430\u043d\u0430\u043b\u0430\u0445 \u2014 \u0432\u043b\u0430\u0434\u0435\u043b\u0435\u0446 \u0438 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440\u044b.\n\n\u2014 EN \u2014\n\nRelease 1.1.25 \u2014 pinned messages.\n\n\ud83d\udccc Pin a message. Anything important can be pinned and stays visible at the top of the chat \u2014 in direct messages, groups and channels. Pin several: the bar shows how many there are, and tapping it cycles through them and jumps to each message.\n\n\ud83d\udccb Pinned list. A separate screen with every pinned message in the chat: jump to any of them, unpin one, or clear them all at once.\n\n\ud83d\ude48 Hide the bar. If you do not need the pinned message right now, tap the cross \u2014 it hides for you only, and comes back when something new is pinned.\n\n\ud83c\udf99 By voice. Ask the assistant to pin or unpin a message, or to tell you what is pinned in a chat.\n\nIn direct messages anyone can pin; in groups and channels the owner and admins can.";
